 const max=Math.max(1,...d.trend.map(x=>x.received));
 el.innerHTML=`<div class="dashboard-heading"><div><div class="eyebrow">INDIVIDUAL PERFORMANCE · HISTORICAL EXTRACT</div><h2>My response intelligence</h2><p>Measures recorded seller activity and the existing worked definition separately. As-of ${esc(d.as_of)}; this is not a live CRM feed.</p></div><div class="field"><label for="adMetricQuarter">Quarter</label><select id="adMetricQuarter"><option value="Q3">Q3 2026</option><option value="Q2">Q2 2026</option><option value="ALL">Both quarters</option></select></div></div><div class="hero-stats">${kpi('MQLs ASSIGNED',num(d.total),'Current assigned owner in extract + demo')}${kpi('WORKED BY CRM STATUS',`${d.historical_status_worked_pct}%`,`${d.historical_status_worked} of ${d.total}`)}${kpi('MY ACTIVITY WITHIN SLA',`${d.within_sla_own_activity_pct}%`,`${d.within_sla_own_activity} of ${d.total}`)}${kpi('MEDIAN FIRST ACTIVITY',d.median_first_response_hours===null?'—':`${d.median_first_response_hours}h`,'Recorded activity, not confirmed conversation')}</div><div class="split"><section class="panel"><div class="panel-head"><div><h3>Monthly lead intake & response</h3><p>Same event-window matching used in the diagnosis</p></div></div><div class="panel-body">${d.trend.map(x=>`<div class="metric-month"><div class="metric-month-title">${esc(x.month)}</div>${trendBar('Received',x.received,max)}${trendBar('My activity within SLA',x.own_activity_on_time,max,'#1185bd')}</div>`).join('')||'<div class="empty">No MQL events for this selection.</div>'}</div></section><section class="panel"><div class="panel-head"><div><h3>My operating snapshot</h3><p>Historical extract as-of Oct 8, not time since today</p></div></div><div class="panel-body"><div class="metric-pair"><span>Contacts with my logged activity</span><strong>${num(d.with_own_activity)}</strong></div><div class="metric-pair"><span>Open MQL statuses</span><strong>${num(d.unresolved_mql)}</strong></div><div class="metric-pair"><span>Open MQLs past historical SLA</span><strong>${num(d.overdue_as_of_extract)}</strong></div><div class="metric-pair"><span>Actions recorded in this demo</span><strong>${num(d.local_action_records)}</strong></div></div></section></div><section class="panel"><div class="panel-head"><div><h3>Intent mix</h3><p>Which requests are entering this AD's queue?</p></div></div>${renderLTable(d.mix,[{key:'form_kind',label:'Form / intent'},{key:'mqls',label:'MQLs'},{key:'reported_worked',label:'Status worked'},{key:'activity_within_sla',label:'My activity in SLA'}])}</section><div class="score-strip"><strong>Metric definitions & limitations</strong>${esc(d.caveat)}</div>`;
