function renderQueueShell(){$('adContent').innerHTML=`<div class="dashboard-heading"><div><div class="eyebrow">ACCOUNT DIRECTOR · ${esc(actor().region)}</div><h2>My lead workspace</h2><p>Your next best actions, ordered by transparent priority rules. Select any lead row to open its entire history and take action.</p></div><div class="button-row">${btn('↻ Refresh','btn-secondary','refreshQueue')}</div></div><div class="hero-stats" id="queueStats">${kpi('ASSIGNED LEADS','—','Loading')}${kpi('NEEDS ACTION','—','Loading')}${kpi('HIGHEST SCORE','—','Loading')}${kpi('CURRENT FILTER','Q3','Loading')}</div><section class="panel"><div class="panel-head"><div><h3>Prioritized MQL queue</h3><p>Click a row to review the account, history, activity, and actions.</p></div><span class="pill" id="countPill">Loading</span></div><div class="filters"><div class="field"><label for="queueQuarter">Quarter</label><select id="queueQuarter"><option value="Q3">Q3 2026</option><option value="Q2">Q2 2026</option><option value="ALL">Both quarters</option></select></div><div class="field"><label for="queueState">Queue state</label><select id="queueState"><option value="needs_action">Needs action</option><option value="all">All leads</option><option value="actioned">Already actioned</option></select></div><div class="field"><label for="queueLane">Workstream</label><select id="queueLane"><option value="ALL">All workstreams</option><option>Hand-raisers</option><option>CS review</option><option>Qualified fit</option><option>Nurture / low signal</option><option>Aged / recycle review</option></select></div><div class="field search"><label for="queueSearch">Search leads</label><input id="queueSearch" placeholder="Name, account, email, MQL ID…" /></div></div><div class="table-wrap" id="queueTable"></div></section><div class="score-strip"><strong>Why not a predictive model?</strong>A conversion model would be trained on only two quarters, with unreliable labels and broken notification/routing history. It might learn *who received an alert* rather than *who will buy*. Our explainable score combines form intent, fit, P1, seniority, validated opportunity context and a limited recency bonus; personal email and missing account matches are visible cautionary signals, not automatic rejection. Scores are ranking points, not conversion probabilities. Model evaluation becomes appropriate after capture integrity and outcome labels are validated.</div>`;$('queueQuarter').value=app.quarter;$('queueState').value=app.queueState;$('queueLane').value=app.queueLane;$('queueSearch').value=app.search;$('refreshQueue').onclick=loadQueue;$('queueQuarter').onchange=()=>{app.quarter=$('queueQuarter').value;loadQueue()};$('queueState').onchange=()=>{app.queueState=$('queueState').value;loadQueue()};$('queueLane').onchange=()=>{app.queueLane=$('queueLane').value;loadQueue()};let timer;$('queueSearch').oninput=()=>{app.search=$('queueSearch').value;clearTimeout(timer);timer=setTimeout(loadQueue,200)};loadQueue()}
async function loadQueue(){try{const p=new URLSearchParams({quarter:app.quarter,state:app.queueState,search:app.search,lane:app.queueLane});const data=await api('/api/queue?'+p);app.queue=data.rows;const high=Math.max(0,...app.queue.map(r=>r.queue_score||0));$('queueStats').innerHTML=kpi('FILTERED LEADS',num(app.queue.length),'Currently assigned to you')+kpi('NEEDS ACTION',num(app.queue.filter(x=>x.needs_ad_action).length),'Of the filtered queue')+kpi('HIGHEST SCORE',num(high),'Relative priority points')+kpi('QUARTER',app.quarter==='ALL'?'Q2 + Q3':app.quarter,'Historical event period');$('countPill').textContent=`${num(data.total)} leads`;if(!app.queue.length){$('queueTable').innerHTML='<div class="empty">No assigned leads match these filters. Try “All leads” or change the quarter.</div>';return}$('queueTable').innerHTML=`<table class="data-table"><thead><tr><th>Score ↓</th><th>Lead</th><th>Account</th><th>Intent</th><th>Workstream</th><th>Status</th><th>Created</th><th>Priority</th><th>Trust</th><th></th></tr></thead><tbody>${app.queue.map(l=>`<tr data-lead="${esc(l.mql_id)}" tabindex="0"><td><span class="score">${num(l.queue_score)}</span></td><td><div class="person">${esc(l.contact_name)}</div><div class="sub">${esc(l.mql_id)}</div></td><td>${esc(l.account_name||'Unmatched account')}</td><td>${esc(l.form_kind)}</td><td>${esc(l.queue_lane)}</td><td>${tag(l.effective_status)}</td><td>${date(l.mql_timestamp)}</td><td>${esc(l.priority)}</td><td>${l.trust_flags?.length?`<span class="pill failed" title="${esc(l.trust_flags.join("; "))}">Review ${l.trust_flags.length}</span>`:`<span class="pill">OK</span>`}</td><td><span style="color:#0c9c80;font-size:20px">↗</span></td></tr>`).join('')}</tbody></table>`;document.querySelectorAll('[data-lead]').forEach(el=>{el.onclick=()=>openLead(el.dataset.lead);el.onkeydown=e=>{if(e.key==='Enter')openLead(el.dataset.lead)}})}catch(e){toast(e.message,true)}}
const detailItem=(key,val)=>`<div class="detail-kv"><small>${key}</small><strong>${esc(val)}</strong></div>`;
function displayTimeline(data,kind){if(!data?.length)return `<div class="muted micro">No ${kind.replace('_',' ')} records in supplied files.</div>`;return `<div class="drawer-timeline">${data.map(x=>{let t='',desc='';if(kind==='status_history'){t=`${x.old_status||'—'} → ${x.new_status||'—'}`;desc=`${x.changed_by||'Unknown'} · ${date(x.changed_at)}`;}else if(kind==='local_actions'){t=x.action_type;desc=`${x.actor} · ${date(x.occurred_at)}${x.new_status?' · '+x.new_status:''}${x.note?' · '+x.note:''}`}else if(kind==='activities'){t=x.activity_type||x.type||'Activity';desc=`${x.user_id||''} · ${date(x.timestamp)}`}else if(kind==='routing'){t=`${x.assigned_to||x.new_owner||x.to_user||'Routing event'}`;desc=Object.entries(x).filter(([k])=>k!=='mql_id').slice(0,3).map(([k,v])=>`${k}: ${v}`).join(' · ')}else {t=x.delivered===true||String(x.delivered).toLowerCase()==='true'?'Delivered alert':'Undelivered alert';desc=`${x.channel||'channel unknown'} · ${date(x.sent_at)}`};return `<div class="drawer-event"><strong>${esc(t)}</strong><span>${esc(desc)}</span></div>`}).join('')}</div>`}
