function renderLeadAdvisory(a){if(!a)return '';return `<section class="advisory-card"><div class="advisory-label"><span class="advisory-sparkle">✦</span> NEXT BEST ACTION <span class="advisory-source">${a.source==='claude_advisory_only'?'CLAUDE / REVIEW':'EXPLAINABLE RULE'}</span></div><h3>${esc(a.title||a.action_type)}</h3><p>${esc(a.rationale)}</p><div class="advisory-actions">${a.blocked||!a.action_type?'<span class="pill simulated">No AD action recommended</span>':`<button id="prepareAdAction" class="btn btn-primary" type="button">Prepare suggested action ↓</button>${a.source!=='claude_advisory_only'?'<button id="draftAdAI" class="btn btn-secondary" type="button">✦ Ask Claude for suggestion</button>':''}`}</div>${a.email_draft?`<div class="advisory-draft"><div class="advisory-draft-head"><strong>Editable email draft · NOT SENT</strong><button id="copyDraft" class="btn btn-secondary" type="button">Copy draft</button></div><p><strong>${esc(a.email_subject||'Email draft')}</strong></p><pre>${esc(a.email_draft)}</pre></div>`:''}<div class="micro muted" style="margin-top:11px">Human confirmation required · No email sent · No Salesforce mutation.</div></section>`}
function bindLeadAdvisory(){const area=$('advisoryRoot');if(!area)return;
 const prepare=$('prepareAdAction');if(prepare)prepare.onclick=()=>{const a=app.selectedLead.next_action;$('actionType').value=a.action_type;renderConditional();if(a.action_type==='Log outreach'&&a.channel&&$('actionChannel'))$('actionChannel').value=a.channel;const note=$('actionNote');if(a.source==='claude_advisory_only'&&a.rationale){note.value=`AI suggestion (reviewed by AD): ${a.rationale}`}else if(a.rationale)note.value=`Suggested context (verify): ${a.rationale}`;$('actionType').scrollIntoView({behavior:'smooth',block:'center'});toast('Action prepared. Review details and click Save to record it. Nothing was sent.')};
 const ai=$('draftAdAI');if(ai)ai.onclick=async()=>{const id=app.selectedLead?.lead?.mql_id;if(!id)return;ai.disabled=true;ai.textContent='Requesting Claude...';try{const r=await api('/api/ad/next-action',{method:'POST',body:JSON.stringify({mql_id:id})});if(app.selectedLead?.lead?.mql_id!==id)return;app.selectedLead.next_action=r.advisory;area.innerHTML=renderLeadAdvisory(r.advisory);bindLeadAdvisory()}catch(e){toast(e.message,true);ai.disabled=false;ai.textContent='✦ Ask Claude for suggestion'}};
 const copy=$('copyDraft');if(copy)copy.onclick=async()=>{const a=app.selectedLead.next_action;try{await navigator.clipboard.writeText(`${a.email_subject||'Draft'}\n\n${a.email_draft}`);toast('Draft copied; not sent.')}catch(e){toast('Clipboard unavailable; select and copy the draft manually.',true)}};
}
function drawLead(){const d=app.selectedLead,l=d.lead;let time=data=>data.length?data:null;$('modalRoot').innerHTML=`<div class="drawer-backdrop" id="drawerOverlay"></div><div class="drawer" role="dialog" aria-modal="true" aria-label="Lead details"><div class="drawer-head"><div><div class="eyebrow">${esc(l.mql_id)} · PRIORITY SCORE ${esc(l.queue_score)}</div><h2>${esc(l.contact_name||'Unnamed contact')}</h2><div class="muted micro" style="margin-top:5px">${esc(l.account_name||'Unmatched account')} · ${tag(l.effective_status)}</div></div><button class="drawer-close" id="closeDrawer" aria-label="Close details">×</button></div><div class="drawer-body"><div id="advisoryRoot">${renderLeadAdvisory(d.next_action)}</div>${renderJourney(d.journey||[])}<div class="drawer-section"><h4>Account & contact context</h4><div class="detail-grid">${detailItem('EMAIL',l.email)}${detailItem('TITLE / SENIORITY',[l.title,l.seniority].filter(Boolean).join(' · '))}${detailItem('ACCOUNT FIT',l.fit_tier||'Unscored')}${detailItem('REGION',l.region)}${detailItem('FORM / INTENT',l.form_name||l.form_kind)}${detailItem('PRIORITY',l.priority)}${detailItem('CAMPAIGN',l.campaign_name)}${detailItem('MQL CREATED',date(l.mql_timestamp))}${detailItem('SLA DEADLINE',date(l.sla_deadline))}${detailItem('CURRENT OWNER',getUser(l.effective_owner)?.name||l.effective_owner)}${detailItem('SOURCE STATUS',l.status_today)}${detailItem('ACTIONS IN DEMO',l.demo_action_count)}${detailItem('ACCOUNT SEGMENT',d.related.account?.segment)}${detailItem('CUSTOMER STATUS',d.related.account?.customer_status)}${detailItem('PRODUCT INTEREST',d.related.submission?.product_interest)}${detailItem('ACCOUNT DOMAIN',d.related.account?.domain)}</div></div>${l.data_warning?`<div class="alert">⚠ Data quality signal: ${esc(l.data_warning)}</div>`:''}<div class="drawer-section"><h4>Why this lead is ranked here</h4><div class="score-explanation">${(l.score_explanation||[]).map(x=>`<div class="explain-row"><span>${esc(x.signal)}</span><strong>${x.points>0?'+':''}${x.points}</strong></div>`).join('')||'<span class="micro muted">No positive scoring signals.</span>'}</div><p class="micro muted">Priority points, not a probability of conversion. Rule changes are manager-reviewed.</p>${l.trust_flags?.length?`<div class="alert">${l.trust_flags.map(esc).join(' · ')}</div>`:''}<div class="notice" style="margin-top:10px"><strong>Pre-qualification guidance: ${esc(l.qualification_suggestion?.decision)}</strong><div class="micro">${esc(l.qualification_suggestion?.basis)}. This is rule-based guidance, not an automated disposition.</div>${l.qualification_approved?`<div class="micro" style="margin-top:8px"><strong>Approved manager disposition: ${esc(l.qualification_approved)}</strong></div>`:""}</div></div><div class="drawer-section"><h4>Historical status changes</h4>${displayTimeline(d.related.status_history,'status_history')}</div><div class="drawer-section"><h4>Routing history</h4>${displayTimeline(d.related.routing,'routing')}</div><div class="drawer-section"><h4>Notification history</h4>${displayTimeline(d.related.notifications,'notifications')}</div><div class="drawer-section"><h4>Seller activity near this MQL</h4>${displayTimeline(d.related.activities,'activities')}</div><div class="drawer-section"><h4>Related opportunities (${d.related.opportunities?.length||0})</h4>${d.related.opportunities?.length?d.related.opportunities.map(o=>`<div class="detail-kv" style="margin-bottom:8px"><small>${esc(o.opp_id)} · ${esc(o.product)}</small><strong>${esc(o.stage)} · ${esc(o.type)} · $${num(o.amount||0)}</strong></div>`).join(''):'<div class="muted micro">No opportunity linked to this contact or account in the source file.</div>'}</div><div class="drawer-section"><h4>LeadLoop action trail</h4>${displayTimeline(d.related.local_actions,'local_actions')}</div><div class="drawer-section"><h4>Take an action</h4><div class="form-actions"><div class="field"><label for="actionType">Action type</label><select id="actionType"><option value="Log outreach">Log outreach</option><option value="Change status">Change status</option><option value="Reassign">Reassign</option><option value="Flag data issue">Flag data issue</option><option value="Return to marketing">Return to marketing</option></select></div><div id="conditionalFields"></div><div class="field"><label for="actionNote" id="noteLabel">Notes <span style="font-weight:400">(optional)</span></label><textarea id="actionNote" placeholder="Add context for marketing and the next AD…"></textarea></div><div class="micro muted" style="margin:12px 0 16px">Recorded as <strong>${esc(actor().name)}</strong> (${esc(app.session.sub)}). Changes remain in the local action ledger.</div><button id="submitAction" class="btn btn-primary" style="width:100%">Save action & update marketing  →</button></div></div></div></div>`;$('drawerOverlay').onclick=closeDrawer;$('closeDrawer').onclick=closeDrawer;document.addEventListener('keydown',escapeDrawer,{once:true});$('actionType').onchange=renderConditional;renderConditional();$('submitAction').onclick=submitAction;bindLeadAdvisory()}
function escapeDrawer(e){if(e.key==='Escape')closeDrawer()}
function renderConditional(){
  const lead=app.selectedLead?.lead;
  if(!lead)return;
  const type=$('actionType').value;
  const fields=$('conditionalFields');
  let html='';
  if(type==='Log outreach'){
    html=`<div class="field"><label for="actionChannel">Outreach channel</label><select id="actionChannel"><option>Call</option><option>Email</option><option>Meeting</option><option>Task</option></select></div>`;
  }else if(type==='Change status'){
    html=`<div class="field"><label for="newStatus">New status</label><select id="newStatus"><option>Working</option><option>Accepted</option><option>Disqualified</option><option>Converted</option><option>MQL</option></select></div><div id="reasonCodeField"></div>`;
  }else if(type==='Reassign'){
    // The selected lead is part of app.selectedLead, not a local variable in this scope.
    // In cases of missing territory, restrict to the signed-in AD's region and require a reason.
    const missingRegion=!lead.region;
    const eligibleRegion=lead.region||actor().region;
    const destinations=app.users.filter(user=>user.user_id!==lead.effective_owner&&user.region===eligibleRegion);
    if(destinations.length){
      html=`<div class="field"><label for="reassignTo">Reassign to another AD</label><select id="reassignTo" required><option value="">Select an AD...</option>${destinations.map(user=>`<option value="${esc(user.user_id)}">${esc(user.name)} · ${esc(user.region)}</option>`).join('')}</select></div>`;
      html+=missingRegion
        ?`<div class="alert">This lead has no verified region. Only ADs in your own region are shown. Add a note explaining why this transfer makes sense; territory validation remains necessary.</div>`
        :`<div class="micro muted" style="margin-top:6px">Showing active ADs in ${esc(eligibleRegion)}. Cross-region transfers require management review.</div>`;
    }else{
      html=`<div class="alert">No other active AD is available in this region. Please ask Marketing Ops to review the territory.</div>`;
    }
  }else if(type==='Flag data issue'){
    html=`<div class="alert">Describe the inaccurate or missing field so Marketing Ops can review it.</div>`;
  }else if(type==='Return to marketing'){
    html=`<div class="alert">Request a Marketing Ops decision. The lead will leave the AD action queue until Marketing returns it.</div>`;
  }
  fields.innerHTML=html;
  const reasons=app.reasonCodes.length?app.reasonCodes:['No fit / wrong segment','Not interested / no intent','Duplicate / already engaged','Existing customer / CS','Wrong contact / role','Timing / nurture','Bad data / enrichment','Other / needs investigation'];
  const drawReason=()=>{const div=$('reasonCodeField')||fields; if(type==='Return to marketing'||(type==='Change status'&&$('newStatus')?.value==='Disqualified')){div.innerHTML+=`<div class="field"><label for="actionReasonCode">Reason category (required)</label><select id="actionReasonCode"><option value="">Select a reason...</option>${reasons.map(r=>`<option value="${esc(r)}">${esc(r)}</option>`).join('')}</select></div>`}else if(div===fields){div.innerHTML=''}else{div.innerHTML=''}};
  const updateRequired=()=>{
    drawReason();
    const required=type==='Flag data issue'||type==='Return to marketing'||
      (type==='Change status'&&$('newStatus')?.value==='Disqualified')||
      (type==='Reassign'&&!lead.region);
    $('actionNote').required=required;
    $('noteLabel').innerHTML=`Notes <span style="font-weight:450;color:${required?'#b64f45':'#8b9eaa'}">(${required?'required':'optional'})</span>`;
    $('actionNote').placeholder=required
      ?(type==='Reassign'?'Explain why this AD is the right owner despite the missing region…':'Explain the issue or why the lead is being disqualified…')
      :'Add context for marketing and the next AD…';
  };
  if($('newStatus'))$('newStatus').onchange=updateRequired;
  if(type==='Reassign'){
    const destination=$('reassignTo');
    $('submitAction').disabled=true;
    if(destination)destination.onchange=()=>{$('submitAction').disabled=!destination.value};
  }else $('submitAction').disabled=false;
  updateRequired();
}
async function submitAction(){
  const lead=app.selectedLead?.lead;
  if(!lead)return toast('Select a lead first.',true);
  const type=$('actionType').value;
  const notes=$('actionNote').value.trim();
  const payload={mql_id:lead.mql_id,action_type:type,note:notes};
  if(type==='Log outreach')payload.channel=$('actionChannel')?.value;
  if(type==='Change status')payload.new_status=$('newStatus')?.value;
  if(type==='Return to marketing'||(type==='Change status'&&payload.new_status==='Disqualified')){
    payload.reason_code=$('actionReasonCode')?.value;
    if(!payload.reason_code)return toast('Select a structured reason category.',true);
  }
  if(type==='Reassign'){
    payload.assigned_to=$('reassignTo')?.value;
    if(!payload.assigned_to)return toast('Choose another active AD before saving.',true);
    if(!lead.region&&!notes)return toast('Explain the territory exception in Notes.',true);
  }
  if(((type==='Change status'&&payload.new_status==='Disqualified')||type==='Flag data issue'||type==='Return to marketing')&&!notes){
    return toast('Please add a note explaining this action.',true);
  }
  const button=$('submitAction');
  button.disabled=true;
  try{
    await api('/api/actions',{method:'POST',body:JSON.stringify(payload)});
    toast(type==='Reassign'?'Lead reassigned. The new AD has been notified in the outbox.':'Action saved. Marketing feedback updated.');
    closeDrawer();
    await loadQueue();
    if(type!=='Reassign')await openLead(lead.mql_id);
  }catch(error){
    toast(error.message,true);
    button.disabled=false;
  }
}
function renderManagerShell(){$('workspaceView').innerHTML=`<div class="dashboard-heading"><div><div class="eyebrow">MARKETING OPERATIONS · MANAGEMENT</div><h2>Funnel command center</h2><p>Trace lead status, seller feedback, and delivery health. Historical source metrics are not overwritten by demo actions.</p></div><div class="button-row">${btn('↻ Refresh','btn-secondary','managerRefresh')}</div></div><div class="page-tabs" id="managerTabs"><button data-mtab="overview">Funnel overview</button><button data-mtab="feedback">Sales feedback</button><button data-mtab="integrations">Integrations & alerts</button><button data-mtab="qualification">Qualification review</button><button data-mtab="rules">Priority rules</button><button data-mtab="quality">Data guard</button><button data-mtab="loop">LeadLoop feedback</button></div><div id="managerContent"></div>`;$('managerRefresh').onclick=loadManager;document.querySelectorAll('[data-mtab]').forEach(b=>b.onclick=()=>{app.managerTab=b.dataset.mtab;drawManager()});loadManager()}
async function loadManager(){try{app.managerData=await api('/api/manager?quarter='+app.managerQuarter);drawManager()}catch(e){toast(e.message,true)}}
async function assignUnassigned(mql){const assigned_to=$('assign-'+mql)?.value;if(!assigned_to)return toast('Choose an AD to assign this lead.',true);try{await api('/api/manager/assign',{method:'POST',body:JSON.stringify({mql_id:mql,assigned_to,note:'Manual manager queue triage; verify territory if original region is missing'})});toast(`Lead ${mql} assigned. Slack event queued.`);await loadManager()}catch(e){toast(e.message,true)}}
function renderLTable(rows,cols){if(!rows.length)return '<div class="empty">No records yet.</div>';return `<div class="table-wrap ledger-table"><table class="data-table"><thead><tr>${cols.map(c=>`<th>${esc(c.label)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${cols.map(c=>`<td>${esc(c.format?c.format(r[c.key],r):r[c.key])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function drawManager(){const d=app.managerData;if(!d)return;document.querySelectorAll('[data-mtab]').forEach(b=>b.classList.toggle('active',b.dataset.mtab===app.managerTab));const el=$('managerContent');if(app.managerTab==='overview'){const max=Math.max(1,...d.status_distribution.map(x=>x.count));el.innerHTML=`<div class="filters" style="background:transparent;padding:0 0 20px;border:0"><div class="field"><label for="managerQuarter">Period</label><select id="managerQuarter"><option value="Q3">Q3 2026</option><option value="Q2">Q2 2026</option><option value="ALL">Both quarters</option></select></div></div><div class="hero-stats">${kpi('TOTAL MQLs',num(d.counts.total),'Source event count')}${kpi('WORKED IN SLA',pct(d.counts.worked_historical,d.counts.total),`${d.counts.worked_historical} of ${d.counts.total}`)}${kpi('NEEDS ACTION',num(d.counts.needs_action),'Based on current local state')}${kpi('LOCAL ACTIONS',num(d.counts.local_actions),'Recorded in LeadLoop')}</div>${app.managerQuarter==='Q3'?`<div class="score-strip" style="margin:-9px 0 22px"><strong>Q3 adjusted adoption · ${pct(app.diagnosis.operational.adjusted_adoption_numerator,app.diagnosis.operational.adjusted_adoption_denominator)} (${num(app.diagnosis.operational.adjusted_adoption_numerator)} / ${num(app.diagnosis.operational.adjusted_adoption_denominator)})</strong>After excluding ${num(app.diagnosis.operational.delivery_ownership_risk_buckets)} ownership/alert risk cases. Stricter sensitivity: ${pct(app.diagnosis.operational.comparable_proxy_numerator,app.diagnosis.operational.comparable_proxy_denominator)} (${num(app.diagnosis.operational.comparable_proxy_numerator)} / ${num(app.diagnosis.operational.comparable_proxy_denominator)}). Recorded actions are an adoption proxy, not verified human conversations.</div>`:''}<div class="split"><section class="panel"><div class="panel-head"><div><h3>Current lead statuses</h3><p>Historical status + actions recorded in this app</p></div></div><div class="panel-body">${d.status_distribution.map(s=>`<div class="distribution-row"><span>${esc(s.status)}</span><div class="fill-track"><div style="width:${s.count*100/max}%"></div></div><strong>${s.count}</strong></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><div><h3>Regional response</h3><p>Reported historical worked versus MQL volume</p></div></div>${renderLTable(d.by_region,[{key:'region',label:'Region'},{key:'mqls',label:'MQLs'},{key:'worked',label:'Worked'},{key:'actions',label:'Demo actions'}])}</section></div><section class="panel"><div class="panel-head"><div><h3>Owner distribution</h3><p>Monitor uneven assignment and feedback</p></div></div>${renderLTable(d.by_owner,[{key:'effective_owner',label:'Assigned AD'},{key:'mqls',label:'MQLs'},{key:'worked',label:'Within SLA'},{key:'actions',label:'Demo actions'}])}</section><section class="panel"><div class="panel-head"><div><h3>Adoption after delivery & mix adjustment</h3><p>Observed seller-action evidence among MQLs delivered to active ADs, excluding existing customers. Expectations standardized by hand-raiser and A/B fit mix — descriptive, not causal.</p></div></div>${renderLTable(d.team_comparison,[{key:'region',label:'AD region'},{key:'routed',label:'Routed'},{key:'not_comparable',label:'Excluded'},{key:'comparable',label:'Comparable'},{key:'action_proxy',label:'Actions'},{key:'rate_pct',label:'Observed %'},{key:'mix_expected_actions',label:'Expected #'}, {key:'actual_vs_expected',label:'Obs / Exp'}])}<div class="bar-foot" style="padding:12px 25px">An activity log is a proxy, not verified contact. Team differences may reflect hidden lead mix and staffing changes; do not rank individual ADs from this table.</div></section><section class="panel"><div class="panel-head"><div><h3>Unassigned-lead triage</h3><p>${num(d.counts.without_owner)} leads currently in the system queue · show top 10 by score · assign an AD to trigger a Slack notification.</p></div></div>${d.unassigned.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Score</th><th>Lead</th><th>Region</th><th>Intent</th><th>Assign to</th><th></th></tr></thead><tbody>${d.unassigned.map(l=>`<tr><td class="score">${num(l.queue_score)}</td><td><div class="person">${esc(l.contact_name)}</div><div class="sub">${esc(l.account_name)} · ${esc(l.mql_id)}</div></td><td>${l.region?esc(l.region):'<span class="pill failed">Missing · review territory</span>'}</td><td>${esc(l.form_kind)}</td><td><select aria-label="Assign ${esc(l.mql_id)}" id="assign-${esc(l.mql_id)}"><option value="">Select an AD</option>${d.ads.filter(u=>!l.region||u.region===l.region).map(u=>`<option value="${esc(u.user_id)}">${esc(u.name)} · ${esc(u.region)}</option>`).join('')}</select></td><td><button type="button" class="btn btn-soft" data-assign="${esc(l.mql_id)}">Assign →</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No leads currently unassigned in this period.</div>'}<div class="bar-foot" style="padding:15px 25px">Assignments are logged as manager actions and an outbox message is queued for Slack. The source CSV remains unchanged.</div></section>`;$('managerQuarter').value=app.managerQuarter;$('managerQuarter').onchange=()=>{app.managerQuarter=$('managerQuarter').value;loadManager()};document.querySelectorAll('[data-assign]').forEach(b=>b.onclick=()=>assignUnassigned(b.dataset.assign))}
 if(app.managerTab==='feedback'){el.innerHTML=`<div class="hero-stats">${kpi('FEEDBACK EVENTS',num(d.actions.length),'Latest 100 shown')}${kpi('MQLs IN SELECTED WINDOW',num(d.counts.total),'Current period')}${kpi('LOCAL ACTIONS',num(d.counts.local_actions),'All leads in period')}${kpi('EXPORT','CSV','Entire append-only audit')}</div><section class="panel"><div class="panel-head"><div><h3>Actions returned to marketing</h3><p>Includes actor, timestamp, type, status, structured reason and free-text justification.</p></div><button class="btn btn-primary" id="exportActions">↓ Export feedback CSV</button></div>${renderLTable(d.actions,[{key:'occurred_at',label:'Recorded at'},{key:'actor',label:'Actor'},{key:'mql_id',label:'MQL'},{key:'action_type',label:'Action'},{key:'new_status',label:'New status'},{key:'assigned_to',label:'Assigned to'},{key:'reason_code',label:'Reason category'},{key:'note',label:'Notes'}])}</section><section class="panel"><div class="panel-head"><div><h3>Marketing review inbox (${num(d.counts.marketing_review)})</h3><p>AD returns awaiting a human decision. Enter a reason to return the lead to its assigned AD, or investigate in CRM.</p></div></div>${d.returned_to_marketing.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Lead</th><th>Owner</th><th>Reason for release</th><th></th></tr></thead><tbody>${d.returned_to_marketing.map(l=>`<tr><td>${esc(l.contact_name)}<div class="sub">${esc(l.mql_id)}</div></td><td>${esc(l.effective_owner)}</td><td><input id="return-note-${esc(l.mql_id)}" placeholder="Required: why send back to AD" /></td><td><button class="btn btn-soft" data-release="${esc(l.mql_id)}">Return to AD →</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No leads are awaiting Marketing review.</div>'}</section><div class="score-strip"><strong>What the feedback does — and does not — mean</strong>An outreach record is a seller-declared action, not a verified email or call. These local events are immediately visible to marketing, without retroactively altering the historical worked metric. Production would synchronize with Salesforce tasks/status changes and verify delivery.</div>`;$('exportActions').onclick=()=>{window.location.href='/api/manager/export'};document.querySelectorAll('[data-release]').forEach(b=>b.onclick=async()=>{const id=b.dataset.release,note=$('return-note-'+id)?.value.trim();if(!note||note.length<5)return toast('Explain why the lead is being returned to the AD.',true);try{await api('/api/manager/return-to-ad',{method:'POST',body:JSON.stringify({mql_id:id,note})});toast('Returned to AD. Notification queued.');await loadManager()}catch(e){toast(e.message,true)}})}
 if(app.managerTab==='integrations'){const sample=d.by_owner.length?'M01107':'M00001';el.innerHTML=`<div class="split"><section class="panel"><div class="panel-head"><div><h3>Slack event delivery</h3><p>Outbox, deduplication and retry pipeline</p></div>${tag(d.integrations.slack_mode)}</div><div class="panel-body"><div class="integration-status">${d.integrations.slack_mode==='live'?'Live Slack credentials detected. Explicit tests may send real messages.':'Offline simulation. Messages are marked simulated; no Slack messages leave the laptop.'}</div><div class="field"><label for="testMql">Test notification on a historical MQL (explicit action only)</label><input id="testMql" value="${esc(sample)}" placeholder="e.g. M01107" /></div><div class="button-row" style="margin-top:12px"><button class="btn btn-primary" id="enqueueAlert">Queue test notification</button><button class="btn btn-secondary" id="flushAlerts">Process pending now</button></div><div class="notice" style="margin-top:16px">At first startup, all supplied historical IDs are marked as seen. Only newly appearing MQL IDs are automatically queued. Historical tests require an explicit manager click.</div></div></section><section class="panel"><div class="panel-head"><div><h3>Salesforce architecture</h3><p>Adapter prepared, not connected to a real org</p></div>${tag('scaffold')}</div><div class="panel-body"><div class="integration-status">Read/write methods use Salesforce REST conventions and query pagination. No real Salesforce mutations are enabled in this demo.</div><div class="code-box">CSV source (now)        Salesforce SOQL (future)\n       └───────────────┬─────────────┘\n            Normalized MQL events\n                     ↓\n                LeadLoop\n                     ↓\n        Local auditable action ledger\n                     ↓\n      Salesforce API writeback (planned)</div><p class="micro muted" style="margin-top:12px">Requires tenant OAuth, real Salesforce record IDs, validated object/field mapping, permission checks, event/owner mapping, idempotent sync, and failure recovery.</p></div></section></div><section class="panel"><div class="panel-head"><div><h3>Notification audit trail</h3><p>Unique event key, delivery attempts, channel, final state and errors</p></div></div>${renderLTable(d.outbox,[{key:'created_at',label:'Queued at'},{key:'mql_id',label:'MQL'},{key:'channel',label:'Channel'},{key:'state',label:'State'},{key:'attempts',label:'Attempts'},{key:'last_error',label:'Last error'}])}</section>`;$('enqueueAlert').onclick=async()=>{try{const res=await api('/api/manager/test-alert',{method:'POST',body:JSON.stringify({mql_id:$('testMql').value.trim()})});toast(`Alert queued in ${res.mode} mode.`);await loadManager()}catch(e){toast(e.message,true)}};$('flushAlerts').onclick=async()=>{try{const res=await api('/api/manager/run-alerts',{method:'POST'});toast(`${res.processed} alert(s) processed.`);await loadManager()}catch(e){toast(e.message,true)}}}
 if(app.managerTab==='qualification')drawQualification();
 if(app.managerTab==='rules')drawRules();
 if(app.managerTab==='quality')drawDataGuard();if(app.managerTab==='loop')drawLoop();
}

async function drawQualification(){
 const el=$('managerContent');el.innerHTML='<section class="panel"><div class="panel-body"><h3>Loading qualification review...</h3></div></section>';
 try{const d=await api('/api/manager/qualification?quarter='+app.managerQuarter);if(app.managerTab!=='qualification')return;
   app.qualData=d;let rows=d.rows;let pending=rows.filter(r=>!r.review&&!r.control);
   el.innerHTML=`<div class="dashboard-heading"><div><div class="eyebrow">HUMAN-IN-THE-LOOP · PRE-AD QUALIFICATION</div><h2>Protect seller time without hiding demand</h2><p>Rules identify review candidates. A person approves the outcome. No MQL is automatically disqualified, and high-intent requests stay with an AD.</p></div><a class="btn btn-secondary" href="/api/manager/qualification/export" style="margin-top:6px">↓ Export qualification decisions</a></div><div class="hero-stats">${kpi('AWAITING REVIEW',num(d.pending),'Excluding experimental holdout')}${kpi('CONTROL GROUP',num(d.control),'Stable ~20% of review candidates')}${kpi('VISIBLE CANDIDATES',num(rows.length),'Existing customers + unmatched accounts')}${kpi('AUTO REJECTED','0','No model-authorized dispositions')}</div><section class="panel qualification-panel"><div class="panel-head"><div><h3>Review candidates</h3><p>Control cases are shown for comparison, not automatically held. Approved decisions are appended to the local audit ledger; Salesforce/CS integration remains simulated.</p></div><span class="pill">${num(pending.length)} pending</span></div><div class="table-wrap qualification-wrap"><table class="data-table qualification-table"><thead><tr><th>Lead</th><th>Reason</th><th>Experiment</th><th>Review decision</th><th>Decision + justification</th></tr></thead><tbody>${rows.slice(0,80).map(r=>`<tr><td class="lead-cell"><div class="person">${esc(r.contact_name)}</div><div class="sub">${esc(r.mql_id)} · ${esc(r.account_name||'No account')}</div></td><td class="reason-cell"><strong>${esc(r.suggestion.decision)}</strong><div class="sub">${esc(r.suggestion.basis)}</div></td><td class="experiment-cell">${r.control?'<span class="pill">Control</span>':'<span class="pill">Treatment</span>'}</td><td class="status-cell">${r.review?`<span class="pill">${esc(r.review.decision)}</span><div class="sub">${esc(r.review.actor)}</div>`:'<span class="pill failed">Pending review</span>'}</td><td class="decision-cell">${r.control?'<span class="pill">No intervention · control group</span>':`<div class="qual-review-form"><select id="qdec-${esc(r.mql_id)}"><option value="">Choose...</option>${d.decisions.map(x=>`<option value="${esc(x)}" ${x===r.suggestion.decision?'selected':''}>${esc(x)}</option>`).join('')}</select><textarea id="qnote-${esc(r.mql_id)}" rows="4" placeholder="Required: evidence and reason"></textarea><div class="qual-review-actions"><button class="btn btn-soft" data-review="${esc(r.mql_id)}">Record review</button>${d.ai_available?`<button class="btn btn-secondary" data-ai-review="${esc(r.mql_id)}">Draft AI suggestion (optional)</button>`:""}</div></div>`}</td></tr>`).join('')}</tbody></table></div><div class="bar-foot">A missing account is an enrichment question, not proof of a bad lead. The SDR explanation in the reference version is a hypothesis only: the historical staffing model is not in the supplied CSVs.</div></section><section class="panel"><div class="panel-head"><div><h3>Backtest: is there evidence for an automatic reject rule?</h3><p>Based ONLY on MQLs where a seller made a first status decision. These labels are selection-biased, not ground truth.</p></div></div>${renderLTable(d.backtest.backtest,[{key:'condition',label:'Candidate rule'},{key:'decided',label:'Seller decisions'},{key:'rejected',label:'Rejected'},{key:'rejection_rate',label:'Rejection %'}])}<div class="bar-foot" style="padding:12px 25px">${esc(d.backtest.caveat)} There is no demonstrated reliable rule for rejecting leads autonomously.</div></section>`;
   document.querySelectorAll('[data-ai-review]').forEach(b=>b.onclick=async()=>{const id=b.dataset.aiReview;b.disabled=true;try{const r=await api('/api/manager/qualification/ai-suggest',{method:'POST',body:JSON.stringify({mql_id:id})});const a=r.advisory;$('qdec-'+id).value=a.decision;$('qnote-'+id).value=`AI DRAFT ONLY — requires human validation. ${a.rationale}\nObserved: ${(a.observed_evidence||[]).join('; ')}\nMissing: ${(a.missing_evidence||[]).join('; ')}\nConfidence: ${a.confidence} (uncalibrated).` ;toast(a.guardrail||'AI proposal drafted. Review evidence and edit before submitting.')}catch(e){toast(e.message,true)}finally{b.disabled=false}});
   document.querySelectorAll('[data-review]').forEach(b=>b.onclick=async()=>{const id=b.dataset.review,decision=$('qdec-'+id).value,reason=$('qnote-'+id).value.trim();if(!decision||!reason)return toast('Select a disposition and add an evidence-based reason.',true);try{await api('/api/manager/qualification/review',{method:'POST',body:JSON.stringify({mql_id:id,decision,reason})});toast('Review recorded for Marketing Ops.');drawQualification()}catch(e){toast(e.message,true)}})
 }catch(e){toast(e.message,true)}
}
async function drawRules(){
 const el=$('managerContent');el.innerHTML='<section class="panel"><div class="panel-body">Loading priority settings...</div></section>';
 try{const d=await api('/api/manager/rules');if(app.managerTab!=='rules')return;app.rulesData=d;
 el.innerHTML=`<div class="dashboard-heading"><div><div class="eyebrow">MARKETING OPS · NO ENGINEER REQUIRED</div><h2>Explainable scoring controls</h2><p>Change ranking weights without code. Server validation enforces bounds; every edit is audited. Undo is a new config event.</p></div></div><div class="panel"><div class="panel-head"><div><h3>Rule weights</h3><p>These are relative ranking points, not calibrated probabilities.</p></div><button class="btn btn-secondary" id="undoRules">↶ Undo last change</button></div><div class="panel-body"><div class="rule-grid">${Object.entries(d.weights).map(([k,v])=>`<div class="field"><label for="rule-${esc(k)}">${esc(k.replaceAll('_',' '))} <small class="muted">(${d.bounds[k][0]} … ${d.bounds[k][1]})</small></label><input id="rule-${esc(k)}" type="number" step="1" min="${d.bounds[k][0]}" max="${d.bounds[k][1]}" value="${v}" /></div>`).join('')}</div><div class="field" style="margin-top:16px"><label for="rulesReason">Change justification (required)</label><textarea id="rulesReason" placeholder="e.g. Increase hand-raiser priority while monitoring disqualification rates"></textarea></div><button class="btn btn-primary" id="saveRules" style="margin-top:12px">Apply and audit changes</button></div></div><section class="panel"><div class="panel-head"><div><h3>Seller disposition categories</h3><p>Manage mandatory rejection / return reasons without editing code. Existing action records are never rewritten.</p></div><button class="btn btn-secondary" id="undoReasons">↶ Undo categories</button></div><div class="panel-body"><div class="field"><label for="reasonCategories">Available reason categories (one per line)</label><textarea id="reasonCategories" rows="9" spellcheck="false">${esc(d.reason_codes.join('\n'))}</textarea></div><div class="field"><label for="reasonJustification">Change justification (required)</label><textarea id="reasonJustification" rows="2" placeholder="Explain why the category list changes"></textarea></div><button class="btn btn-primary" id="saveReasons">Save disposition categories</button></div></section><section class="panel" style="margin-top:18px"><div class="panel-head"><h3>Recent approved changes</h3></div>${renderLTable(d.history,[{key:'changed_at',label:'When'},{key:'actor',label:'Actor'},{key:'reason',label:'Why'}])}</section>`;
 $('saveRules').onclick=async()=>{const weights=Object.fromEntries(Object.keys(d.weights).map(k=>[k,Number($('rule-'+k).value)]));try{await api('/api/manager/rules',{method:'POST',body:JSON.stringify({weights,reason:$('rulesReason').value})});toast('Scores updated for all leads; change audited.');drawRules()}catch(e){toast(e.message,true)}};
 $('saveReasons').onclick=async()=>{const codes=$('reasonCategories').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);try{await api('/api/manager/reason-codes',{method:'POST',body:JSON.stringify({codes,justification:$('reasonJustification').value})});toast('Reason categories updated and audited.');drawRules()}catch(e){toast(e.message,true)}};
 $('undoReasons').onclick=async()=>{try{await api('/api/manager/reason-codes/undo',{method:'POST'});toast('Previous categories restored.');drawRules()}catch(e){toast(e.message,true)}};
 $('undoRules').onclick=async()=>{try{await api('/api/manager/rules/undo',{method:'POST'});toast('Previous weights restored.');drawRules()}catch(e){toast(e.message,true)}};
 }catch(e){toast(e.message,true)}
}
function drawDataGuard(){let c=app.managerData?.data_checks||[];$('managerContent').innerHTML=`<div class="dashboard-heading"><div><div class="eyebrow">PIPELINE INVARIANTS · EVIDENCE-BASED</div><h2>Data guard</h2><p>Checks recompute on every data load. They never silently modify source records or fabricate qualification outcomes.</p></div></div><div class="guard-grid">${c.map(x=>`<div class="panel"><div class="panel-head"><div><div class="eyebrow">${esc(x.severity)} · ${esc(x.id)}</div><h3>${esc(x.title)}</h3></div><strong class="big-count">${num(x.count)}</strong></div><div class="panel-body"><div class="micro muted"><strong>Evidence:</strong> ${esc(x.evidence)}</div><p style="margin-top:10px"><strong>Next action:</strong> ${esc(x.action)}</p></div></div>`).join('')}</div><div class="score-strip"><strong>What this tool does not assume</strong>A check count is not a causal effect. Historical owner activity, genuine seller contact, and whether unmatched forms were suppressed intentionally require upstream logs or interviews.</div>`}
async function logout(){try{await api('/api/logout',{method:'POST'});}catch(e){}app.session=null;closeDrawer();gate()}
async function bootstrap(){try{const [diag,people,ses]=await Promise.all([api('/api/diagnosis'),api('/api/users'),api('/api/session')]);app.diagnosis=diag;app.users=people.ads;app.session=ses.session;app.complete=safeSession.get('ql_story_done')==='1';if(app.session){app.complete=true;workspace()}else{app.step=0;app.highest=0;story()}}catch(e){$('storyView').innerHTML=`<div class="story-copy"><h2>Unable to load case files.</h2><p>${esc(e.message)}</p><p>Run <code>python server.py</code> and confirm the data folder contains the supplied 14 CSVs.</p></div>`}}
$('navStory').onclick=()=>{app.step=0;story()};$('navWorkflow').onclick=()=>workflowPage();$('navRoadmap').onclick=()=>roadmapPage();$('navWorkspace').onclick=()=>{if(!app.complete)return toast('Complete the investigation first.',true);app.session?workspace():gate()};$('accountBtn').onclick=logout;bootstrap();
